package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.RuntimeIntStore;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Engineering interface for Vanilla Sculk/calibrated-sensor vibration-frequency redstone output, with event diagnostics. */
public class SculkVibrationInterfaceBlock extends PassiveDirectionalSignalBlock{private static final String KEY="sculk_interface";public SculkVibrationInterfaceBlock(Properties p){super(p);}@Override public MapCodec<SculkVibrationInterfaceBlock> codec(){return RedstoneEngineering.SCULK_VIBRATION_INTERFACE_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.max(0,Math.min(15,l.getSignal(inputPos(p,s),inputSide(s))));}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,1);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int[]rt=RuntimeIntStore.get(l,KEY,p,5);int now=computeOutput(l,p,s);if(now>0&&rt[0]==0){rt[1]++;rt[2]=now;rt[3]=(int)Math.min(Integer.MAX_VALUE,l.getGameTime());}if(now!=rt[0])rt[4]++;rt[0]=now;updateOutput(l,p,s,now);l.scheduleTick(p,this,1);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){if(pl.isShiftKeyDown()){RuntimeIntStore.remove(l,KEY,p);pl.displayClientMessage(Component.literal("Sculk event diagnostics reset"),true);}else{int[]rt=RuntimeIntStore.get(l,KEY,p,5);pl.displayClientMessage(Component.literal("Sculk event code="+outputValue(l,p,s)+"/15 last="+rt[2]+" events="+rt[1]+" transitions="+rt[4]),true);}}return InteractionResult.sidedSuccess(l.isClientSide);}}
